examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
struct Node: Identifiable, Hashable {
    let id: String
    let name: String
    let detail: String
    var children: [Node]?
}
@State private var selection: String? = {{selected.0}}
@State private var expanded: Set<String> = [{{expanded.0}}, {{expanded.1}}]

/// One node and, when it is open, its children: a leading chevron for a node with children, the name over its detail,
/// the edit button at the end, and the selected row in the accent tint with an accent edge.
private func row(_ node: Node, depth: Int = 0) -> AnyView {
    let hasChildren = !(node.children ?? []).isEmpty
    let isOpen = expanded.contains(node.id)
    let isSelected = selection == node.id
    let line = HStack(spacing: theme.spacing.space1) {
        if hasChildren {
            Button {
                if isOpen { expanded.remove(node.id) } else { expanded.insert(node.id) }
            } label: {
                Image(systemName: isOpen ? "chevron.down" : "chevron.right")
                    .foregroundStyle(theme.colors.textMuted)
                    .frame(width: 24, height: 44)
            }
            .buttonStyle(.plain)
            .accessibilityLabel(node.name)
            .accessibilityValue(isOpen ? "Expanded" : "Collapsed")
        } else {
            Color.clear.frame(width: 24, height: 44)
        }
        Button {
            selection = node.id
        } label: {
            VStack(alignment: .leading) {
                Text(node.name).monarchTextStyle(.body)
                Text(node.detail).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isSelected ? .isSelected : [])
        MonarchButton("\({{editLabel}}) \(node.name)", systemImage: "pencil", variant: .ghost, size: .sm, isIconOnly: true) {}
    }
    .padding(.leading, CGFloat(depth) * theme.spacing.space5)
    .background(isSelected ? theme.colors.accentSubtle : Color.clear, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
    .overlay(alignment: .leading) {
        if isSelected {
            Capsule().fill(theme.colors.accentSolid).frame(width: 2)
        }
    }
    return AnyView(
        VStack(alignment: .leading, spacing: 0) {
            line
            if hasChildren && isOpen {
                ForEach(node.children ?? []) { child in row(child, depth: depth + 1) }
            }
        }
    )
}
